#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
constexpr int64 MOD = 1'000'000'007LL;

int64 modPow(int64 base, int64 exponent) {
    int64 result = 1;
    while (exponent > 0) {
        if (exponent & 1LL) result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1LL;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    vector<int64> n(t);
    int64 maximum = 0;

    for (int i = 0; i < t; ++i) {
        cin >> n[i];
        if (n[i] < MOD) maximum = max(maximum, n[i]);
    }

    vector<int64> factorial(static_cast<size_t>(maximum) + 1, 1);
    for (int64 i = 1; i <= maximum; ++i) {
        factorial[i] = factorial[i - 1] * i % MOD;
    }

    for (int64 value : n) {
        int64 fact = (value >= MOD) ? 0 : factorial[value];
        int64 answer = (fact - modPow(2, value - 1) + MOD) % MOD;
        cout << answer << '\n';
    }

    return 0;
}

