#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll MOD = 1000000007;

ll modPow(ll base, ll exp) {
    ll result = 1;
    while (exp > 0) {
        if (exp & 1) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    vector<ll> n(t), factorial(t);
    vector<pair<ll, int>> queries;

    for (int i = 0; i < t; ++i) {
        cin >> n[i];
        if (n[i] >= MOD)
            factorial[i] = 0;
        else
            queries.push_back({n[i], i});
    }

    sort(queries.begin(), queries.end());

    ll currentFactorial = 1;
    ll currentN = 0;

    for (auto [target, index] : queries) {
        while (currentN < target) {
            ++currentN;
            currentFactorial = currentFactorial * currentN % MOD;
        }
        factorial[index] = currentFactorial;
    }

    for (int i = 0; i < t; ++i) {
        ll answer = (factorial[i] - modPow(2, n[i] - 1) + MOD) % MOD;
        cout << answer << '\n';
    }

    return 0;
}

